import regionData from "@/data/shopCountryRegions.json";

/** First-level subdivisions per ISO country code, generated by
 * `scripts/generate-shop-country-regions.mjs` (Unicode CLDR; Ukraine curated). */
type RegionRecord = { code: string; en: string; uk?: string };

const REGIONS = regionData.regions as Record<string, RegionRecord[]>;

export type ShopCountryRegion = { code: string; name: string };

export function getShopCountryRegions(
  countryCode: string | null | undefined,
  locale: "ua" | "en"
): ShopCountryRegion[] {
  const list = REGIONS[String(countryCode ?? "").toUpperCase()] ?? [];
  // Ukrainian names only for Ukraine: an address abroad must stay in Latin
  // script for the foreign carrier.
  return list.map((region) => ({
    code: region.code,
    name: locale === "ua" && region.uk ? region.uk : region.en,
  }));
}

export function shopCountryHasRegions(countryCode: string | null | undefined) {
  return (REGIONS[String(countryCode ?? "").toUpperCase()]?.length ?? 0) > 0;
}

/**
 * The subdivision code ("UA-32") for a listed name in either language, or for the code
 * itself; null when the country does not list it. Lets rules match across languages.
 */
export function shopCountryRegionCode(
  countryCode: string | null | undefined,
  region: string | null | undefined
): string | null {
  const wanted = String(region ?? "").trim().toLowerCase();
  if (!wanted) return null;
  const entry = (REGIONS[String(countryCode ?? "").toUpperCase()] ?? []).find(
    (item) =>
      item.code.toLowerCase() === wanted ||
      item.en.toLowerCase() === wanted ||
      item.uk?.toLowerCase() === wanted
  );
  return entry?.code ?? null;
}

/** Whether `region` is one of the country's listed names, in either language. */
export function isShopCountryRegion(countryCode: string | null | undefined, region: string) {
  const wanted = region.trim().toLowerCase();
  return (REGIONS[String(countryCode ?? "").toUpperCase()] ?? []).some(
    (entry) => entry.en.toLowerCase() === wanted || entry.uk?.toLowerCase() === wanted
  );
}
